    handleTrades(client, message) {
        //
        //     {
        //         data: {
        //             E: '1754601477746429',
        //             T: '1754601477744000',
        //             a: '5121860761',
        //             b: '5121861755',
        //             e: 'trade',
        //             m: false,
        //             p: '3870.25',
        //             q: '0.0008',
        //             s: 'ETH_USDC_PERP',
        //             t: 10782547
        //         },
        //         stream: 'trade.ETH_USDC_PERP'
        //     }
        //
        const data = this.safeDict(message, 'data', {});
        const marketId = this.safeString(data, 's');
        const market = this.market(marketId);
        const symbol = market['symbol'];
        if (!(symbol in this.trades)) {
            const limit = this.safeInteger(this.options, 'tradesLimit', 1000);
            const stored = new ArrayCache(limit);
            this.trades[symbol] = stored;
        }
        const cache = this.trades[symbol];
        const trade = this.parseWsTrade(data, market);
        cache.append(trade);
        const messageHash = 'trades:' + symbol;
        client.resolve(cache, messageHash);
        client.resolve(cache, 'trades');
    }
    parseWsTrade(trade, market = undefined) {
        //
        //     {
        //         E: '1754601477746429',
        //         T: '1754601477744000',
        //         a: '5121860761',
        //         b: '5121861755',
        //         e: 'trade',
        //         m: false,
        //         p: '3870.25',
        //         q: '0.0008',
        //         s: 'ETH_USDC_PERP',
        //         t: 10782547
        //     }
        //
        const microseconds = this.safeInteger(trade, 'E', 0);
        const timestamp = this.parseToInt(microseconds / 1000);
        const id = this.safeString(trade, 't');
        const marketId = this.safeString(trade, 's');
        const marketResolved = this.safeMarket(marketId, market);
        const isBuyerMaker = this.safeBool(trade, 'm');
        let side = undefined;
        let takerOrMaker = undefined;
        if (isBuyerMaker !== undefined) {
            takerOrMaker = 'taker';
            if (isBuyerMaker) {
                side = 'sell';
            }
            else {
                side = 'buy';
            }
        }
        const price = this.safeString(trade, 'p');
        const amount = this.safeString(trade, 'q');
        let orderId = undefined;
        if (side === 'buy') {
            orderId = this.safeString(trade, 'b');
        }
        else {
            orderId = this.safeString(trade, 'a');
        }
        return this.safeTrade({
            'info': trade,
            'id': id,
            'timestamp': timestamp,
            'datetime': this.iso8601(timestamp),
            'symbol': marketResolved['symbol'],
            'order': orderId,
            'type': undefined,
            'side': side,
            'takerOrMaker': takerOrMaker,
            'price': price,
            'amount': amount,
            'cost': undefined,
            'fee': {
                'currency': undefined,
                'cost': undefined,
            },
        }, marketResolved);
    }
